-- =============================================================================
-- V188 — Zones and regions from OCCPL's pincode master (Pincode_Master_NEW - SHUBHAM, shared on 2026-11-27).
-- Generated by a script from the sheet, do not edit. Follows V187, which cleared every zone, region and rate.
--
-- Owner's rule: **zone = the sheet's zone column, region = the sheet's Region column.**
--   * Regional Zones master (global): the 7 Regions — PUNE, X_PUNE, MAHARASHTRA, X_MAHARASHTRA, VIDHARBHA, REST_OF_INDIA, NORTH_EAST
--     (sheet EXPUNE / EXMAHARASHTRA = X_PUNE / X_MAHARASHTRA). Old deleted rows holding these codes are renamed
--     (~V188) first: the master's unique key (company_id, code) does not look at `deleted`.
--   * Every pincode the sheet lists (19127): Zone = the zone column, Regional zone = its Region.
--     Zone: SOUTH 6652, NORTH 4483, EAST 4262, WEST 2698, CENTRAL 1032.
--     Region: REST_OF_INDIA 13281, NORTH_EAST 4262, X_MAHARASHTRA 999, VIDHARBHA 301, MAHARASHTRA 222, PUNE 50, X_PUNE 12.
--   * Zone Tariff, companies OCCPL and OCCPL_COURIER — the owner's pricing rule "first the Region's rate, then the
--     zone's" (customer sheets are priced from PUNE to PUNE, EXPUNE, MAHARASHTRA, EXMAHARASHTRA, VIDHARBHA, NORTH EAST,
--     WEST, CENTRAL, SOUTH, NORTH, EAST, METRO):
--       - 7 Region zones PUNE, X_PUNE, MAHARASHTRA, X_MAHARASHTRA, VIDHARBHA, REST_OF_INDIA, NORTH_EAST (From and To),
--         each with one place: its whole regional zone. Every pincode resolves to its Region's zone.
--       - 6 more To zones NORTH, SOUTH, EAST, WEST, CENTRAL, METRO with no places: a card's lane to one of them is used
--         when the card has no rate to the pincode's Region zone and the pincode master's Zone names it
--         (TariffQuoteServiceImpl). METRO has no pincode yet (it is in neither column of the sheet).
--     No rate cards: they are uploaded next.
-- Pincodes not on file are not added; the pincode's coverage, TAT and ODA are untouched.
-- =============================================================================

SET @g = UNHEX('00000000000000000000000000000001');
SET @now = UTC_TIMESTAMP(6);

-- 1. Regional Zones master ----------------------------------------------------------------------------------
UPDATE master_regional_zones
SET code = CONCAT(LEFT(code, 30), '~V188-', LEFT(HEX(id), 8)), updated_at = @now
WHERE company_id = @g AND deleted = TRUE AND code IN ('PUNE', 'X_PUNE', 'MAHARASHTRA', 'X_MAHARASHTRA', 'VIDHARBHA', 'REST_OF_INDIA', 'NORTH_EAST');

SELECT UNHEX(REPLACE(UUID(), '-', '')), @g, 'PUNE', 'Pune', 'Region of the OCCPL pincode master (V188)', 'ACTIVE', 0, @now, @now, FALSE, 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM master_regional_zones WHERE company_id = @g AND code = 'PUNE' AND deleted = FALSE);
SELECT UNHEX(REPLACE(UUID(), '-', '')), @g, 'X_PUNE', 'X - Pune', 'Region of the OCCPL pincode master (V188)', 'ACTIVE', 1, @now, @now, FALSE, 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM master_regional_zones WHERE company_id = @g AND code = 'X_PUNE' AND deleted = FALSE);
SELECT UNHEX(REPLACE(UUID(), '-', '')), @g, 'MAHARASHTRA', 'Maharashtra', 'Region of the OCCPL pincode master (V188)', 'ACTIVE', 2, @now, @now, FALSE, 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM master_regional_zones WHERE company_id = @g AND code = 'MAHARASHTRA' AND deleted = FALSE);
SELECT UNHEX(REPLACE(UUID(), '-', '')), @g, 'X_MAHARASHTRA', 'X - Maharashtra', 'Region of the OCCPL pincode master (V188)', 'ACTIVE', 3, @now, @now, FALSE, 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM master_regional_zones WHERE company_id = @g AND code = 'X_MAHARASHTRA' AND deleted = FALSE);
SELECT UNHEX(REPLACE(UUID(), '-', '')), @g, 'VIDHARBHA', 'Vidharbha', 'Region of the OCCPL pincode master (V188)', 'ACTIVE', 4, @now, @now, FALSE, 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM master_regional_zones WHERE company_id = @g AND code = 'VIDHARBHA' AND deleted = FALSE);
SELECT UNHEX(REPLACE(UUID(), '-', '')), @g, 'REST_OF_INDIA', 'Rest of India', 'Region of the OCCPL pincode master (V188)', 'ACTIVE', 5, @now, @now, FALSE, 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM master_regional_zones WHERE company_id = @g AND code = 'REST_OF_INDIA' AND deleted = FALSE);
SELECT UNHEX(REPLACE(UUID(), '-', '')), @g, 'NORTH_EAST', 'North East', 'Region of the OCCPL pincode master (V188)', 'ACTIVE', 6, @now, @now, FALSE, 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM master_regional_zones WHERE company_id = @g AND code = 'NORTH_EAST' AND deleted = FALSE);

-- 2. Pincodes: zone and region ------------------------------------------------------------------------------
DROP TABLE IF EXISTS tmp_v188_pin;
CREATE TABLE tmp_v188_pin (pincode CHAR(6) NOT NULL PRIMARY KEY, zone VARCHAR(20) NOT NULL, region VARCHAR(30) NOT NULL)
    ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

UPDATE master_pincodes p
JOIN tmp_v188_pin t ON t.pincode = p.code
JOIN master_regional_zones rz ON rz.company_id = @g AND rz.code = t.region AND rz.deleted = FALSE
SET p.zone = t.zone, p.regional_zone_id = rz.id, p.updated_at = @now
WHERE p.company_id = @g AND p.deleted = FALSE;

-- 3. Zone Tariff zones and places -----------------------------------------------------------------------------
DROP TABLE IF EXISTS tmp_v188_co;
CREATE TABLE tmp_v188_co (company_id BINARY(16) NOT NULL PRIMARY KEY) ENGINE = InnoDB;
SELECT company_id FROM companies WHERE company_code IN ('OCCPL', 'OCCPL_COURIER') AND deleted = FALSE;

DROP TABLE IF EXISTS tmp_v188_zone;
CREATE TABLE tmp_v188_zone (code VARCHAR(30) NOT NULL PRIMARY KEY, name VARCHAR(100) NOT NULL, ord INT NOT NULL,
                            usage_ VARCHAR(10) NOT NULL, region BOOLEAN NOT NULL)
    ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

                          created_at, updated_at, deleted, version)
SELECT UNHEX(REPLACE(UUID(), '-', '')), c.company_id, t.code, t.name, t.usage_,
       IF(t.region, 'Region of the pincode master (V188)', 'Zone of the pincode master: rate used when there is none for the Region (V188)'),
       t.ord, 'ACTIVE', @now, @now, FALSE, 0
FROM tmp_v188_co c
JOIN tmp_v188_zone t
WHERE NOT EXISTS (SELECT 1 FROM tariff_zones z WHERE z.company_id = c.company_id AND z.code = t.code AND z.deleted = FALSE);

-- One place per Region zone: its whole regional zone.
SELECT UNHEX(REPLACE(UUID(), '-', '')), z.company_id, z.id, 'REGIONAL_ZONE', rz.id, @now, @now, FALSE, 0
FROM tariff_zones z
JOIN tmp_v188_co c ON c.company_id = z.company_id
JOIN tmp_v188_zone t ON t.code = z.code AND t.region
JOIN master_regional_zones rz ON rz.company_id = @g AND rz.code = z.code AND rz.deleted = FALSE
WHERE z.deleted = FALSE;

UPDATE tariff_zones z JOIN tmp_v188_co c ON c.company_id = z.company_id
SET z.location_count = (SELECT COUNT(*) FROM tariff_zone_locations l WHERE l.zone_id = z.id AND l.deleted = FALSE)
WHERE z.deleted = FALSE;

DROP TABLE tmp_v188_zone;
DROP TABLE tmp_v188_co;
DROP TABLE tmp_v188_pin;
